package com.novasoft.psicoapp.model; import jakarta.persistence.*; import java.time.*;
@Entity public class Assignment{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne public CaseStudy caseStudy; @ManyToOne public StudyGroup group; @ManyToOne public User student; @ManyToOne public GameSession gameSession; public int currentBlockIndex=0; public boolean completed=false; public LocalDateTime dueDate; public boolean retryAllowed=true; public int maxAttempts=1; public int extraAttempts=0; }
